-- A rate can carry a from-date: it applies from that date on (a rate with none applies from the beginning
-- of time). A grade may have several rates, one per from-date; a claim uses the one whose from-date is the
-- latest on or before its date.
ALTER TABLE rate ADD COLUMN from_date DATE;
DROP INDEX rate_sheet_grade;
CREATE INDEX rate_sheet_grade ON rate (sheet_id, grade);
-- Who opened a claim: the signed-in name that opened it. Null while it was never opened. The one who
-- opened a claim cannot settle it.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(255);
-- The version of a person: raised by one on every save. An edit names the version it loaded and
-- is refused when someone else has saved the person since.
ALTER TABLE person ADD COLUMN version BIGINT DEFAULT 0 NOT NULL;
-- A person's statement: their due-total when it was taken (n/a when there was none) and the sheet's
-- today then. Their count and last one are read from here.
CREATE TABLE statement (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    due_total VARCHAR(30) NOT NULL,
    taken_on DATE NOT NULL
);
CREATE INDEX statement_person ON statement (person_id, id);
-- A claim bound by its person's last statement shows and totals the figure it had then (stated_due;
-- null when it had none, n/a), until the next statement rebinds or unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(19, 2);
-- A sheet's periods: a name, unique on the sheet, and a from and to date, inclusive. No two periods on a
-- sheet overlap; a claim belongs to the one whose dates contain its date, or to none.
CREATE TABLE period (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name VARCHAR(200) NOT NULL,
    from_date DATE NOT NULL,
    to_date DATE NOT NULL
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name);
-- A period can be closed: its due-total is then fixed at what it was on closing, and no claim dated in it can
-- be added, edited or change status.
ALTER TABLE period ADD COLUMN closed BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(19, 2);
-- The date a person is retired from (null: not retired). A person with one set counts as retired at
-- once, whatever the date; their claims dated after it are refused.
ALTER TABLE person ADD COLUMN retired_from DATE;
-- Whether a person is on hold. While held, their OPEN claims count in no live total (their own claimed and
-- due-total, the sheet's totals, a period's total); their SETTLED claims still count.
ALTER TABLE person ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
-- A sheet's roles: a user name's role on the sheet, clerk or steward. A name with no row is a clerk.
CREATE TABLE sheet_role (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200) NOT NULL,
    role VARCHAR(20) NOT NULL
);
CREATE UNIQUE INDEX sheet_role_user ON sheet_role (sheet_id, user_name);
-- The sheet's clerk limit: a clerk settles a claim only when its due is at or below it. NULL: no limit.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(19, 2);
-- The sheet's floor: a claim's live due is at least it. Two decimals; a sheet starts at 1.00.
ALTER TABLE sheet ADD COLUMN floor DECIMAL(19, 2) DEFAULT 1.00 NOT NULL;
-- A sheet: everything else in the app is kept per sheet. Created the first time its id is loaded.
CREATE TABLE sheet (
    id VARCHAR(200) PRIMARY KEY
);
-- The sheet's terms: a claim is due by its date plus this many days. A sheet starts at 14.
ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL;
-- The sheet's late percent: an overdue claim's due gains this percent of its figure for every full 30 days it is
-- overdue. Two decimals; a sheet starts at 0.00.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(19, 2) DEFAULT 0.00 NOT NULL;
-- A person's patrons: other people on the same sheet they have named, each once. Their backing is the
-- patrons' due-totals added up.
CREATE TABLE person_patron (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    patron_id BIGINT NOT NULL REFERENCES person (id),
    CONSTRAINT person_patron_unique UNIQUE (person_id, patron_id)
);
CREATE INDEX person_patron_sheet ON person_patron (sheet_id, id);
-- A person's dated grades: each save of the person form records its grade from its from-date, replacing the
-- one recorded for that date. The person's own grade is the first one they were given, which applies from the
-- beginning of time.

